def matchAfterOneSwap(s, goal):
    if len(s) != len(goal):
        return False
    diff = [i for i in range(len(s)) if s[i] != goal[i]]
    if not diff:
        return len(set(s)) < len(s)
    if len(diff) != 2:
        return False
    a, b = diff
    return s[a] == goal[b] and s[b] == goal[a]
